const e={remoteControl:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Sende Befehle an den FilaMind-Bildschirm am Drucker."}},status:{ready:{t:0,b:{t:2,i:[{t:3}],s:"Befehlskanal verbunden"}},down:{t:0,b:{t:2,i:[{t:3}],s:"Verbindung zum Befehlskanal wird hergestellt…"}}},show:{title:{t:0,b:{t:2,i:[{t:3}],s:"Auf dem Bildschirm anzeigen"}},status:{t:0,b:{t:2,i:[{t:3}],s:"Status"}},control:{t:0,b:{t:2,i:[{t:3}],s:"Steuerung"}},settings:{t:0,b:{t:2,i:[{t:3}],s:"Einstellungen"}}},locate:{title:{t:0,b:{t:2,i:[{t:3}],s:"Bildschirm finden"}},hint:{t:0,b:{t:2,i:[{t:3}],s:"Lass den Bildschirm aufleuchten, damit du erkennst, zu welchem Drucker er gehört."}},button:{t:0,b:{t:2,i:[{t:3}],s:"Bildschirm finden"}}},message:{title:{t:0,b:{t:2,i:[{t:3}],s:"Nachricht senden"}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:"Gib eine kurze Nachricht für den Bildschirm ein…"}},level:{t:0,b:{t:2,i:[{t:3}],s:"Stufe"}},info:{t:0,b:{t:2,i:[{t:3}],s:"Info"}},warn:{t:0,b:{t:2,i:[{t:3}],s:"Warnung"}},send:{t:0,b:{t:2,i:[{t:3}],s:"Senden"}}},sent:{t:0,b:{t:2,i:[{t:3}],s:"Gesendet"}},help:{button:{t:0,b:{t:2,i:[{t:3}],s:"Hilfe"}},title:{t:0,b:{t:2,i:[{t:3}],s:"Fernsteuerung – Anleitung"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Schließen"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Was das bewirkt"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Dieses Panel steuert den FilaMind-Touchscreen am Drucker von hier aus: Wechsle seinen Tab, zeige eine kurze Nachricht an oder lass ihn aufleuchten, um zu erkennen, welcher Drucker es ist. Das sind reine Anzeige-Hinweise – sie bewegen den Drucker nie und ändern keine Einstellung."}}},commands:{title:{t:0,b:{t:2,i:[{t:3}],s:"Die Befehle"}},body:{t:0,b:{t:2,i:[{t:3}],s:"„Anzeigen“ wechselt den Bildschirm zum Tab Status, Steuerung oder Einstellungen. „Finden“ lässt den Bildschirm einige Sekunden aufleuchten. „Nachricht“ zeigt einen kurzen Hinweis (Info oder Warnung). Befehle erreichen jeden FilaMind-Bildschirm an diesem Drucker; während der Befehlskanal noch verbindet, wird nichts gesendet."}}}}}}};exp